    private Rollup rollup(String sheetId) {
        return rollup(sheetId, null);
    }

    /** The sheet's figures as it stood at the end of a day: its people, claims, holds, grades, rates
     *  and settings as they stood then, the day standing in for the sheet's today (null: now). */
    private Rollup rollup(String sheetId, LocalDate asOf) {
        LocalDate today = asOf != null ? asOf : sheets.today(sheetId);
        List<Person> sheetPeople = personService.list(sheetId, asOf);
        Map<Long, List<PersonHold>> holds = personService.holds(sheetId, asOf);
        Map<Long, LocalDate> retiredFrom = new HashMap<>();
        sheetPeople.forEach(person -> retiredFrom.put(person.getId(), person.getRetiredFrom()));
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDesc(sheetId);
        Map<Long, List<Claim>> counted = (asOf == null ? sheetClaims : history.claims(sheetClaims, asOf)).stream()
                .filter(claim -> claim.countsClaimed(retiredFrom.get(claim.getPersonId()), today))
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = NONE;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : sheetPeople) {
            Figures f = figuresOf(sheetId, today, asOf, person, counted.getOrDefault(person.getId(), List.of()),
                    holds.getOrDefault(person.getId(), List.of()), retiredFrom.get(person.getId()));
            figures.put(person.getId(), f);
            claimedTotal = claimedTotal.add(f.claimed());
            if (f.due() != null) {
                dues.add(f.due());
            }
            overdues.add(f.overdue());
        }
        return new Rollup(figures, claimedTotal, trimmedSum(dues), trimmedSum(overdues));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are
     *  three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(NONE, BigDecimal::add);
        if (figures.size() < 3) {
            return sum;
        }
        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
    }

    /** A person's figures from their claims that count: the sum of their amounts, leaving out those
     *  that correct another claim (a held claim's included), and the sum of the
     *  figures shown by those not held, or none when the grade in force on the sheet's today has no rate in force
     *  then and no claim of theirs shows a figure; the sum is held to the sheet's cap. The overdue-total
     *  sums the dues of those that are OPEN or PENDING with a due-by plus their grace before the sheet's today. */
    private Figures figuresOf(String sheetId, LocalDate today, LocalDate asOf, Person person, List<Claim> counted,
            List<PersonHold> holds, LocalDate retiredFrom) {
        BigDecimal claimed = NONE;
        BigDecimal due = NONE;
        BigDecimal overdue = NONE;
        boolean anyFigure = false;
        for (Claim claim : counted) {
            if (claim.getCorrects() == null) {
                claimed = claimed.add(claim.getAmount());
            }
            if (!claim.countsLive(holds, retiredFrom, today)) {
                continue;
            }
            BigDecimal figure = claimService.dueOf(sheetId, person, claim, asOf);
            if (figure != null) {
                due = due.add(figure);
                if (claim.getStatus().isOpen() && claimService.overdueFrom(sheetId, person, claim, asOf).isBefore(today)) {
                    overdue = overdue.add(figure);
    }

    private static BigDecimal sum(Map<Long, BigDecimal> personTotals) {
        return personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Each person's due-total for the period now, by person id, everyone on the sheet. */
    private Map<Long, BigDecimal> personTotals(String sheetId, Period period) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<PersonHold>> holds = personService.holds(sheetId);
        LocalDate today = sheets.today(sheetId);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        byId.keySet().forEach(id -> personTotals.put(id, BigDecimal.ZERO.setScale(2)));
        Map<Long, ClaimStatus> atEnd = claimService.statusesAsOf(sheetId, period.getTo());
        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null
                    || !claim.countsAsOf(atEnd.get(claim.getId()), holds.getOrDefault(person.getId(), List.of()),
                            person.getRetiredFrom(), today)
                    || !period.contains(claim.getDueBy())) {
                continue;
            }
            BigDecimal due = claimService.dueOf(sheetId, person, claim);
            if (due != null) {
                personTotals.merge(person.getId(), due, BigDecimal::add);
            }
        }
        return personTotals;
    }

    /** Each person's carried figure for the period now, by person id, everyone on the sheet: the dues
     *  shown now on their claims whose due-by falls in a period ending before this one starts, that
     *  were still OPEN or PENDING at the end of this period's last day (by the status each had then, as
     *  its status log records it) and the live rules leave in (a claim with no figure adds nothing), and
     *  their opening balance for it. */
    private Map<Long, BigDecimal> personCarried(String sheetId, Period period) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<PersonHold>> holds = personService.holds(sheetId);
        List<Period> all = periods.findBySheetIdOrderByFromAsc(sheetId);
        LocalDate today = sheets.today(sheetId);
        Map<Long, BigDecimal> carried = new LinkedHashMap<>();
        byId.keySet().forEach(id -> carried.put(id, BigDecimal.ZERO.setScale(2)));
        period.getPersonOpenings().forEach((id, amount) -> carried.computeIfPresent(id, (key, sum) -> sum.add(amount)));
        Map<Long, ClaimStatus> atEnd = claimService.statusesAsOf(sheetId, period.getTo());
        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            ClaimStatus then = atEnd.get(claim.getId());
            if (person == null || then == null || !then.isOpen()
                    || !claim.countsAsOf(then, holds.getOrDefault(person.getId(), List.of()),
                            person.getRetiredFrom(), today)
                    || all.stream().noneMatch(own -> own.contains(claim.getDueBy())
                            && own.getTo().isBefore(period.getFrom()))) {
                continue;
            }
            BigDecimal due = claimService.dueOf(sheetId, person, claim);
            if (due != null) {
                carried.merge(person.getId(), due, BigDecimal::add);
            }
        }

